function ensureAudio(){if(!soundOn)return null;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;if(!soundCtx)soundCtx=new C();if(soundCtx.state==='suspended')soundCtx.resume();return soundCtx}catch(e){return null}}
function tone(freq,dur=.12,type='sine',gain=.08,delay=0){const a=ensureAudio();if(!a)return;const t=a.currentTime+delay,o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+dur+.02)}
const FILE_SOUNDS={buzz:'/sounds/buzz.mp3',correct:'/sounds/correct.mp3',wrong:'/sounds/wrong.mp3',timeout:'/sounds/timeout.mp3',pass:'/sounds/pass.mp3',warning:'/sounds/warning.mp3',win:'/sounds/win.mp3',lose:'/sounds/lose.mp3',draw:'/sounds/draw.mp3',teamWin:'/sounds/team-win.mp3'};const soundFiles={};function playFileSound(kind){if(!soundOn)return false;const src=FILE_SOUNDS[kind];if(!src)return false;try{let a=soundFiles[kind];if(!a){a=new Audio(src);a.preload='auto';soundFiles[kind]=a}a.currentTime=0;const p=a.play();if(p&&p.catch)p.catch(()=>{});return true}catch(e){return false}}
function sfx(kind){playFileSound(kind);const key=(room?.number||0)+':'+kind;if(key===lastSfxKey)return;lastSfxKey=key;const map={buzz:[[180,.1,'square',.13],[260,.12,'square',.1]],correct:[[523,.12,'triangle',.1],[659,.12,'triangle',.1],[784,.2,'triangle',.12]],wrong:[[220,.15,'sawtooth',.07],[160,.25,'sawtooth',.06]],timeout:[[180,.15,'square',.08],[120,.25,'square',.07]],pass:[[440,.08,'sine',.06],[330,.12,'sine',.05]],warning:[[330,.1,'square',.06],[220,.18,'square',.05]]};(map[kind]||[]).forEach((n,i)=>tone(...n,i*.08))}
