function connect(){
  if(!me)return;
  if(ws&&ws.readyState<=1)return;
  if(wsReconnectTimer){clearTimeout(wsReconnectTimer);wsReconnectTimer=null}
  const proto=location.protocol==='https:'?'wss':'ws';
  try{ws=new WebSocket(`${proto}://${location.host}/ws?userId=${encodeURIComponent(me.id)}`)}catch(e){scheduleWsReconnect();return}
  ws.onopen=()=>{$('conn').textContent=L().connected;$('conn').className='on';loadInvites()};
  ws.onclose=()=>{$('conn').textContent=L().reconnecting;$('conn').className='off';if(me)scheduleWsReconnect()};
  ws.onerror=()=>{$('conn').textContent=L().reconnecting;$('conn').className='off'};
  ws.onmessage=e=>{try{const m=JSON.parse(e.data),d=m.data;switch(m.event){case'connected':break;case'users':users(d||[]);break;case'invite':invite(d);break;case'roomCreated':api('/api/room?id='+encodeURIComponent(d.roomId)).then(x=>{room=x;show('room');render()});break;case'roomLeft':clearInterval(timer);room=null;show('lobby');renderStatic();users([]);loadInvites();break;case'room':room=d;show('room');render();break;case'restartRequest':showRestartModal(d);break;case'restartResponse':toast(d.accepted?L().restartApproved:L().restartRejected);if(d.accepted)closeRestartModal();break;case'inviteResult':break;}}catch(err){console.warn('WebSocket message error',err)}};
}
