async function challenge(to){
  if(!me||!to)return;
  const selectedMode=$('lobbyMode')?.value;
  const mode=(room?.status==='lobby'&&['1v1','2v2','3v3'].includes(room.mode))?room.mode:(['1v1','2v2','3v3'].includes(selectedMode)?selectedMode:'1v1');
  const roomId=room?.status==='lobby'&&room?.mode===mode?room.id:null;
  try{
    const endpoint=(mode==='2v2'||mode==='3v3')?'/api/team-challenge':'/api/challenge';
    const r=await api(endpoint,{from:me.id,to,mode,roomId});
    if(r?.ok===false||r?.error){toast(r.error==='already_in_room'?(L().teamFull||L().ended):(r.error||L().ended));return}
    toast(L().challengeSent);
  }catch(e){toast(e?.message||L().disconnected||'Connection error')}
  finally{}
}
