function renderChat(){if(!room)return;let list=(room.chat||[]).filter(m=>m.scope===activeChat);$('chatlog').innerHTML=list.map(m=>`<div><b>${esc(m.name)}:</b> ${esc(m.text)}</div>`).join('')||'<span class="empty">—</span>'}
function startMatchClock(){clearInterval(matchTimer);if(!room?.matchEndsAt||room.status==='lobby'||room.status==='starting'||room.status==='finished'||room.status==='draw'){if($('matchTimer'))$('matchTimer').textContent='';return}let warned={};const tick=()=>{const ms=Math.max(0,room.matchEndsAt-Date.now());const sec=Math.ceil(ms/1000);const m=Math.floor(sec/60),s=sec%60;if($('matchTimer')){const el=$('matchTimer');el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;el.parentElement?.classList.toggle('urgent',sec<=30)}if([30,10,5,4,3,2,1].includes(sec)&&!warned[sec]){warned[sec]=1;sfx(sec<=10?'warning':'tick')}if(ms<=0)clearInterval(matchTimer)};tick();matchTimer=setInterval(tick,200)}
function showRestartModal(d){let t=L();$('restartModalTitle').textContent=t.restartIncoming;let text=t.restartIncomingText;if(d.teamBroadcast){const all={ar:`${d.fromName||'القائد'} يريد إعادة المباراة للجميع. هل توافق؟`,en:`${d.fromName||'The team leader'} wants to restart the match for everyone. Do you agree?`,he:`${d.fromName||'מנהל הקבוצה'} רוצה להפעיל מחדש את המשחק לכולם. האם אתה מסכים?`,ru:`${d.fromName||'Капитан команды'} хочет перезапустить матч для всех. Вы согласны?`};text=all[currentLang]||all.ar}else{text=text.replace('اللاعب الآخر',d.fromName||'اللاعب الآخر').replace('the other player',d.fromName||'the other player')}$('restartModalText').textContent=text;$('restartAccept').textContent=t.restartYes;$('restartReject').textContent=t.restartNo;$('restartModal').classList.remove('hidden');$('restartAccept').onclick=()=>respondRestart(true,d.roomId);$('restartReject').onclick=()=>respondRestart(false,d.roomId)}
function closeRestartModal(){$('restartModal').classList.add('hidden')}
async function respondRestart(accept,roomId){closeRestartModal();await api('/api/room/restart/respond',{roomId,userId:me.id,accept})}
function toast(msg){if(!$('toast'))return;$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function playEndSound(won){if(playFileSound(won?'win':'lose'))return;const key=won?'winSound':'lossSound';if(document.body.dataset[key]===String(room?.number))return;document.body.dataset[key]=String(room?.number);try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const a=new C();const now=a.currentTime;const notes=won?[523.25,659.25,783.99,1046.5]:[392,330,261.63,196];notes.forEach((f,i)=>{const o=a.createOscillator(),g=a.createGain();o.type=won?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,now+i*.16);g.gain.exponentialRampToValueAtTime(.16,now+i*.16+.03);g.gain.exponentialRampToValueAtTime(.0001,now+i*.16+.14);o.connect(g);g.connect(a.destination);o.start(now+i*.16);o.stop(now+i*.16+.15)});setTimeout(()=>a.close(),900)}catch(e){}}
function lossEffect(){if(document.body.dataset.lost===String(room.number))return;document.body.dataset.lost=String(room.number);playEndSound(false);let layer=document.createElement('div');layer.className='loss-effect';layer.innerHTML='<div class="loss-face">😔</div><div class="loss-shock">💔</div>';document.body.appendChild(layer);setTimeout(()=>layer.remove(),3300)}
function drawEffect(){if(document.body.dataset.drawn===String(room.number))return;document.body.dataset.drawn=String(room.number);toast(L().drawTitle)}
function restartButtonLabel(){if(!room||room.mode==='1v1'||room.owner!==me?.id)return L().restart;const labels={ar:'🔄 طلب إعادة للجميع',en:'🔄 Request rematch for all',he:'🔄 בקש משחק מחדש לכולם',ru:'🔄 Запросить переигровку для всех'};return labels[currentLang]||labels.ar}
function render(){let t=L(),p=room.players||[];$('buzz').textContent=t.buzz;clearInterval(timer);clearInterval(matchTimer);const teamCounts=room.mode==='1v1'?[room.players.filter(x=>x.id===room.players[0]?.id).length,room.players.length>1?1:0]:[room.players.filter(x=>room.teams?.[x.id]===0).length,room.players.filter(x=>room.teams?.[x.id]===1).length];const teamReady=room.mode==='1v1'||(teamCounts[0]===room.capacity/2&&teamCounts[1]===room.capacity/2);const canStart=room.status==='lobby'&&room.players.length===room.capacity&&teamReady&&room.owner===me?.id;const showStart=room.status==='lobby'&&room.owner===me?.id;$('startGame').style.display=showStart?'block':'none';$('startGame').disabled=!canStart;$('startGame').classList.toggle('not-ready',!canStart);$('startGame').title=canStart?t.start:(room.mode==='1v1'?`${t.ready} — ${room.players.length}/${room.capacity}`:`${t.teamReady}: ${teamCounts[0]}/${room.capacity/2} 🆚 ${teamCounts[1]}/${room.capacity/2}`);$('difficulty').style.display=room.status==='lobby'?'block':'none';if($('matchDuration')){const box=$('matchDuration');box.style.display=room.status==='lobby'?'block':'none';const selected=String(room.matchDuration||5);box.querySelectorAll('input[name="matchDuration"]').forEach(i=>{i.checked=i.value===selected;i.disabled=room.owner!==me?.id});box.classList.toggle('disabled',room.owner!==me?.id)}$('gameActions').style.display=room.status!=='lobby'?'flex':'none';$('restartGame').style.display=room.status!=='lobby'?'inline-flex':'none';$('restartGame').disabled=false;$('restartGame').textContent=restartButtonLabel();$('restartStatus').textContent=room.restartRequested?.includes(me?.id)?t.restartWaiting:'';$('matchTimeLabel').textContent='⏱️ '+t.matchTime;startMatchClock();$('roomHomeBtn').style.display='inline-flex';if(room.mode==='1v1'){$('p1').innerHTML=p[0]?`${p[0].avatar}<br>${esc(p[0].name)}`:'';$('p2').innerHTML=p[1]?`${p[1].avatar}<br>${esc(p[1].name)}`:''}else{$('p1').innerHTML='🟦<br>'+p.filter(x=>room.teams?.[x.id]===0).map(x=>`${x.avatar} ${esc(x.name)}`).join('<br>');$('p2').innerHTML='🟥<br>'+p.filter(x=>room.teams?.[x.id]===1).map(x=>`${x.avatar} ${esc(x.name)}`).join('<br>')}$('scores').innerHTML=room.mode==='1v1'?p.map(x=>`${esc(x.name)}: <b>${room.scores[x.id]||0}</b>`).join('　 VS　 '):`🟦 ${p.filter(x=>room.teams?.[x.id]===0).map(x=>esc(x.name)).join(' + ')}: <b>${room.teamScores?.[0]||0}</b>　 VS　 🟥 ${p.filter(x=>room.teams?.[x.id]===1).map(x=>esc(x.name)).join(' + ')}: <b>${room.teamScores?.[1]||0}</b>`;renderTeams(t,p);$('answers').innerHTML='';$('answers').style.pointerEvents='none';$('answers').style.opacity='.55';$('buzz').disabled=true;$('pass').classList.add('hidden');$('pass').disabled=true;$('timer').textContent='0';
if(room.status==='lobby'){const readyText=room.mode==='1v1'?(room.players.length===room.capacity?t.ready:`${t.ready} — ${room.players.length}/${room.capacity}`):`${t.ready} — ${room.players.length}/${room.capacity} | ${teamCounts[0]}/${room.capacity/2} 🆚 ${teamCounts[1]}/${room.capacity/2}`;$('state').textContent=readyText;$('meta').textContent=t.target;$('difficulty').innerHTML=`<div class="diff-title">${t.difficulty}</div><label><input type="radio" name="difficulty" value="easy" checked> ${t.easy}</label><label><input type="radio" name="difficulty" value="medium"> ${t.medium}</label><label><input type="radio" name="difficulty" value="hard"> ${t.hard}</label><label><input type="radio" name="difficulty" value="expert"> ${t.expert}</label>`;renderChat();return}
if(room.status==='starting'){$('state').textContent=t.getReady;$('meta').textContent=t.target;renderChat();return}
let c=room.current;
if(c){let qt=qText(c);$('meta').textContent=`${esc(qt[2])} — ${t.target} — ${c.number}`;$('question').textContent=qt[0];if(room.status==='question'){$('state').textContent=t.buzz;$('buzz').disabled=false;resetClockVisual()}else if(room.status==='locked'){$('state').textContent=room.lockedBy===me.id?t.yourTurn:t.opponentFirst;if(room.lockedBy===me.id){showAnswers(c);clock(c.deadline)}}else if(room.status==='steal'){$('state').textContent=room.stealBy===me.id?t.steal:t.wrongOpponent;if((room.mode==='1v1'&&room.stealBy===me.id)||(room.mode!=='1v1'&&room.teams?.[me.id]===room.stealTeam)){showAnswers(c);clock(c.deadline);$('pass').classList.remove('hidden');$('pass').disabled=false}}else if(room.status==='correct'||room.status==='wrong'){sfx(room.status==='correct'?'correct':'wrong');if(room.status==='correct'){$('state').textContent=t.correct}else{const mine=room.lockedBy===me.id;const myTeam=room.mode!=='1v1'&&room.teams?.[me.id]===room.teams?.[room.lockedBy];$('state').textContent=mine?(room.mode==='1v1'?t.wrongPassed:t.wrongTeamPassed):(room.mode==='1v1'?t.opponentWrongPassed:(myTeam?t.teamWrongPassed:t.opponentWrongPassed));$('answers').innerHTML='';$('answers').style.pointerEvents='none';$('answers').style.opacity='.55'}}else if(room.status==='timeout'){sfx('timeout');$('state').textContent=t.timeout}}
if(room.status==='finished'){let won=room.mode==='1v1'?room.winner===me.id:room.winnerTeam===room.teams?.[me.id];const timeEnded=room.endReason==='time';const scoreText=room.mode==='1v1'?`${room.scores?.[room.players?.[0]?.id]||0} - ${room.scores?.[room.players?.[1]?.id]||0}`:`${room.teamScores?.[0]||0} - ${room.teamScores?.[1]||0}`;$('state').textContent=won?(timeEnded?t.timeVictoryTitle:t.victoryTitle):t.lossTitle;$('meta').textContent=won?(timeEnded?`${t.timeVictoryHint} (${scoreText})`:t.victoryHint):(timeEnded?`${t.lossHint} (${scoreText})`:t.lossHint);$('buzz').disabled=true;$('answers').style.pointerEvents='none';$('timer').textContent='0';if(won){celebrate();playEndSound(true)}else{lossEffect()}}else if(room.status==='draw'){$('state').textContent=t.drawTitle;$('meta').textContent=t.drawHint;$('buzz').disabled=true;$('answers').style.pointerEvents='none';$('timer').textContent='0';drawEffect()}else if(room.status==='question-bank-empty'){$('state').textContent=t.bankEmptyTitle;$('meta').textContent=t.bankEmptyHint;$('question').textContent=t.questionBankEmpty;$('buzz').disabled=true;$('answers').style.pointerEvents='none';$('timer').textContent='0'}renderChat()}
function showAnswers(c){let qt=qText(c);$('answers').style.pointerEvents='auto';$('answers').style.opacity='1';$('answers').innerHTML=qt[1].map((a,i)=>`<button onclick="answer(${i})">${String.fromCharCode(65+i)}. ${esc(a)}</button>`).join('')}
function resetClockVisual(){$('timer').textContent='0';$('timer').style.setProperty('--progress','0%')}
function clock(d){clearInterval(timer);if(!d){resetClockVisual();return}const seconds={easy:10,medium:12,hard:15,expert:18}[room?.difficulty]||10;const start=d-seconds*1000;let f=()=>{const remaining=Math.max(0,d-Date.now());const pct=Math.max(0,Math.min(100,(remaining/(seconds*1000))*100));$('timer').textContent=Math.ceil(remaining/1000);$('timer').style.setProperty('--progress',pct+'%');if(remaining<=0)clearInterval(timer)};f();timer=setInterval(f,80)}
function toggleChat(force){let p=$('chatPanel');if(!p)return;let hidden=p.classList.contains('hidden');p.classList.toggle('hidden',force===undefined?!hidden:!force)}
async function goHome(){clearInterval(timer);if(room&&me){try{await api('/api/room/leave',{roomId:room.id,userId:me.id})}catch(e){}}closeRealtime();stopInvitePolling();room=null;me=null;try{localStorage.removeItem(USER_KEY)}catch(e){}show('login');$('chatPanel').classList.add('hidden');$('chatlog').innerHTML='';$('invites').innerHTML='<i id="noInvites"></i>';renderStatic()}
function celebrate(){if(document.body.dataset.celebrated===String(room.number))return;document.body.dataset.celebrated=String(room.number);let layer=document.createElement('div');layer.className='celebration';for(let i=0;i<90;i++){let c=document.createElement('i');c.style.left=(Math.random()*100)+'vw';c.style.animationDelay=(Math.random()*0.8)+'s';c.style.transform=`rotate(${Math.random()*360}deg)`;layer.appendChild(c)}document.body.appendChild(layer);setTimeout(()=>layer.remove(),4200)}
async function press(){
 if(!room||!me)return;
 sfx('buzz');$('buzz').disabled=true;
 // In 3v3 there can be six persistent SSE connections on the same origin.
 // Chromium may reserve the connection pool for those streams and delay the
 // gameplay POST. Free this tab's SSE connection for the buzz request, then
 // load the authoritative room state directly and reconnect.
 const teamMode=room.mode==='3v3';
 try{
   const r=await api('/api/room/press',{roomId:room.id,userId:me.id});
   if(teamMode){room=await api('/api/room?id='+encodeURIComponent(room.id));show('room');render()}
   return r;
 }catch(e){
   $('buzz').disabled=false;
   toast(e?.message||L().disconnected||'Connection error');
 }finally{
 
 }
}
async function answer(i){
 if(!room||!me)return;
 document.querySelectorAll('#answers button').forEach(b=>b.disabled=true);
 const teamMode=room.mode==='3v3';
 try{
   const r=await api('/api/room/answer',{roomId:room.id,userId:me.id,answer:i});
   if(teamMode){
     room=await api('/api/room?id='+encodeURIComponent(room.id));
     show('room');render();
   }
   return r;
 }catch(e){
   document.querySelectorAll('#answers button').forEach(b=>b.disabled=false);
   toast(e?.message||L().disconnected||'Connection error');
 }finally{
 
 }
}
async function passTurn(){if(!room)return;sfx('pass');await api('/api/room/pass',{roomId:room.id,userId:me.id})}
async function chat(){let t=$('chattext').value.trim();if(t){$('chattext').value='';await api('/api/room/chat',{roomId:room.id,userId:me.id,text:t,scope:activeChat})}}
async function restartGame(){if(!room||!me)return;const r=await api('/api/room/restart',{roomId:room.id,userId:me.id});if(r?.status==='waiting'&&$('restartStatus'))$('restartStatus').textContent=L().restartWaiting}
setLanguage(currentLang);renderStatic();bindLanguagePicker();
